import 'dart:convert';import 'dart:io';import '../models/app_models.dart';
class ProcessUpdate{ProcessUpdate(this.message,{this.done=false,this.result,this.error});final String message;final bool done;final EngineResult?result;final String?error;}
class LocalEngineService{Process? _active;bool get running=>_active!=null;
 Stream<ProcessUpdate>compress({required String python,required String workingDirectory,required String input,required String output,required String mode,String?checkpoint})async*{final args=['-m','xai_compress','compress',input,output,'--mode',mode,'--overwrite'];if(mode=='neural'){if(checkpoint==null||checkpoint.isEmpty){yield ProcessUpdate('Neural mode requires a checkpoint.',done:true,error:'Checkpoint missing');return;}args.addAll(['--checkpoint',checkpoint]);}yield* _run(python,args,workingDirectory);}
 Stream<ProcessUpdate>decompress({required String python,required String workingDirectory,required String input,required String output,String?checkpoint})async*{final args=['-m','xai_compress','decompress',input,output,'--overwrite'];if(checkpoint!=null&&checkpoint.isNotEmpty)args.addAll(['--checkpoint',checkpoint]);yield* _run(python,args,workingDirectory);}
 Stream<ProcessUpdate>_run(String exe,List<String>args,String cwd)async*{try{_active=await Process.start(exe,args,workingDirectory:cwd,runInShell:true);yield ProcessUpdate('Engine started...');final out=StringBuffer(),err=StringBuffer();await for(final data in _active!.stdout.transform(utf8.decoder)){out.write(data);yield ProcessUpdate(data.trim().isEmpty?'Processing...':data.trim());}await for(final data in _active!.stderr.transform(utf8.decoder)){err.write(data);yield ProcessUpdate(data.trim());}final code=await _active!.exitCode;_active=null;if(code!=0){yield ProcessUpdate('Engine failed.',done:true,error:err.toString());return;}final json=Map<String,dynamic>.from(jsonDecode(out.toString()));yield ProcessUpdate('Completed.',done:true,result:EngineResult.fromJson(json));}catch(e){_active=null;yield ProcessUpdate('Engine error.',done:true,error:e.toString());}}
 void cancel(){_active?.kill(ProcessSignal.sigterm);_active=null;}}
